import React from 'react';
import styled from 'styled-components';

const Services = () => {
    return (
        <div>
            <Title>
                Nasza oferta
            </Title>
            <MainBox>
                <BoxesRow>
                    <ServiceBox>
                        <Subtitle>
                            Oferta 1
                        </Subtitle>
                    </ServiceBox>
                    <Spacer></Spacer>
                    <ServiceBox></ServiceBox>
                </BoxesRow>
                <BoxesRow>
                    <ServiceBox></ServiceBox>
                    <Spacer></Spacer>
                    <ServiceBox></ServiceBox>
                </BoxesRow>
            </MainBox>
        </div>

    );
}

export default Services

const MainBox = styled.div`
    height: 600px;
    background-color: red;
    margin: 48px;
    margin-left: 80px;
    margin-right: 80px;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    justify-content: flex-start;
`;

const Title = styled.h1`
    padding-top: 48px;
    padding-bottom: 48px; 
    text-align: center;
`;

const BoxesRow = styled.div`
    display: flex;
    flex-direction: row;
    height: 600px;
    width: 100%;
    align-items: stretch;
    justify-content: center;
`;

const ServiceBox = styled.div`
    flex: 50%;
    border-radius: 25px;
    background-color: #E5A424;
    width: 40%;
    height: 40%;
`;

const Spacer = styled.div`
    flex: 7%;
`;

const Subtitle = styled.h2`
    text-align: center;
    padding-left: 20px;
    padding-right: 20px;
    color: #fff;
`;
